 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            colors = {grid[y][x] for y, x in cells}
            boxes = {}
            for color in colors:
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (min(y for y, x in pts), max(y for y, x in pts),
                                min(x for y, x in pts), max(x for y, x in pts))
            ordered = sorted(colors, key=lambda color: (
                -((boxes[color][1] - boxes[color][0] + 1) * (boxes[color][3] - boxes[color][2] + 1)),
                color))
            mapping = dict(zip(ordered, reversed(ordered)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
